<script setup lang="ts">
import{computed,onBeforeUnmount,onMounted,reactive,ref}from'vue';import{useRouter}from'vue-router';import{enterpriseApi}from'../services/enterprise';import StatusPill from'../components/StatusPill.vue'
const router=useRouter(),rows=ref<any[]>([]),options=ref<any>({rooms:[],accounts:[],anchors:[]}),loading=ref(true),error=ref(''),updated=ref(''),timer=ref<number>(),total=ref(0),offset=ref(0),limit=ref(24)
const filters=reactive({keyword:'',room_id:'',account_id:'',anchor_id:'',online_state:'',collector_state:'',studio_state:'',agent_version:'',sort:'abnormal',order:'asc'})
const page=computed(()=>Math.floor(offset.value/limit.value)+1),pages=computed(()=>Math.max(1,Math.ceil(total.value/limit.value)))
function params(){const p=new URLSearchParams({limit:String(limit.value),offset:String(offset.value),sort:filters.sort,order:filters.order});Object.entries(filters).forEach(([k,v])=>{if(v&&k!=='sort'&&k!=='order')p.set(k,v)});return p}
async function load(reset=false){if(reset)offset.value=0;loading.value=true;error.value='';try{const response=await enterpriseApi.devices(params());rows.value=response.items||[];total.value=response.pagination?.total||0;updated.value=new Date().toLocaleTimeString()}catch(e:any){error.value=`${e.message}${e.requestId?`（请求编号 ${e.requestId}）`:''}`}finally{loading.value=false}}
async function boot(){try{options.value=await enterpriseApi.options();await load()}catch(e:any){error.value=e.message;loading.value=false}timer.value=window.setInterval(()=>{if(!document.hidden)load()},15000)}
function changePage(value:number){offset.value=(value-1)*limit.value;load()}
onMounted(boot);onBeforeUnmount(()=>{if(timer.value)clearInterval(timer.value)})
</script>
<template><div class="page-stack"><section class="panel"><header class="panel-head"><div><span class="eyebrow">DEVICE OPERATIONS</span><h2>设备中心</h2><p>按异常优先查看实时设备，筛选结果、分页总数和设备详情均来自同一份状态数据。</p></div><div class="update-stamp"><i></i><span>15 秒刷新</span><small>{{updated||'等待首次同步'}}</small></div></header><div class="device-filter-panel"><label class="search-field">搜索设备、直播间、账号或主播<input v-model="filters.keyword" placeholder="输入名称、编号、门店或负责人" @keyup.enter="load(true)"></label><label>直播间<select v-model="filters.room_id"><option value="">全部直播间</option><option v-for="x in options.rooms" :value="String(x.id)">{{x.name}}</option></select></label><label>开播账号<select v-model="filters.account_id"><option value="">全部账号</option><option v-for="x in options.accounts" :value="String(x.id)">{{x.display_name}}</option></select></label><label>主播<select v-model="filters.anchor_id"><option value="">全部主播</option><option v-for="x in options.anchors" :value="String(x.id)">{{x.display_name}}</option></select></label><label>在线状态<select v-model="filters.online_state"><option value="">全部</option><option value="online">在线</option><option value="unstable">不稳定</option><option value="offline">离线</option></select></label><label>采集状态<select v-model="filters.collector_state"><option value="">全部</option><option value="healthy">正常</option><option value="degraded">异常</option><option value="offline">离线</option><option value="unknown">未知</option></select></label><label>直播软件<select v-model="filters.studio_state"><option value="">全部</option><option value="running">运行中</option><option value="not_running">未运行</option><option value="crashed">异常退出</option></select></label><label>客户端版本<input v-model="filters.agent_version" placeholder="例如 2.1.0"></label><label>排序<select v-model="filters.sort"><option value="abnormal">异常优先</option><option value="last_heartbeat_at">最后心跳</option><option value="cpu_percent">CPU</option><option value="memory_percent">内存</option><option value="network_latency_ms">网络延迟</option><option value="upload_mbps">上传带宽</option></select></label><label>顺序<select v-model="filters.order"><option value="asc">升序</option><option value="desc">降序</option></select></label><button class="primary" @click="load(true)">应用筛选</button></div><div class="result-summary"><span>共 <b>{{total}}</b> 台设备</span><span>第 {{page}} / {{pages}} 页</span><button @click="Object.assign(filters,{keyword:'',room_id:'',account_id:'',anchor_id:'',online_state:'',collector_state:'',studio_state:'',agent_version:'',sort:'abnormal',order:'asc'});load(true)">清空筛选</button></div><div v-if="error" class="state-panel error"><span class="state-icon">!</span><h3>设备状态暂时不可用</h3><p>{{error}}</p><button class="primary" @click="load()">重新连接</button></div><div v-else-if="loading&&!rows.length" class="realtime-grid"><i v-for="n in 6" class="skeleton device-card-skeleton"></i></div><div v-else-if="!rows.length" class="empty-state"><b>没有符合筛选条件的设备</b><p>可以清空筛选，或确认客户端已经加入当前企业并成功发送心跳。</p></div><div v-else class="realtime-grid"><article v-for="x in rows" :key="x.device_id" :class="x.online_state" role="button" tabindex="0" @click="router.push({name:'enterprise-device-detail',params:{deviceId:x.device_id}})" @keyup.enter="router.push({name:'enterprise-device-detail',params:{deviceId:x.device_id}})"><header><div><b>{{x.display_name}}</b><small>{{x.device_id}}</small></div><StatusPill :value="x.online_state"/></header><div v-if="x.abnormal_reasons.length" class="reason-strip"><b>{{x.abnormal_reasons[0].message}}</b><span v-if="x.abnormal_reasons.length>1">+{{x.abnormal_reasons.length-1}}</span></div><dl><div><dt>当前绑定</dt><dd>{{x.room?.name||'未绑定直播间'}}</dd></div><div><dt>开播账号</dt><dd>{{x.account?.display_name||'未关联'}}</dd></div><div><dt>直播软件</dt><dd><StatusPill :value="x.studio_state"/></dd></div><div><dt>采集状态</dt><dd><StatusPill :value="x.collector_state"/></dd></div></dl><div class="metric-line"><span>CPU {{x.cpu_percent??'-'}}%</span><span>内存 {{x.memory_percent??'-'}}%</span><span>延迟 {{x.network_latency_ms??'-'}}ms</span><span>上传 {{x.upload_mbps??'-'}}Mbps</span></div><footer><span>V{{x.agent_version||'-'}}</span><span>{{x.last_heartbeat_at?.replace('T',' ').slice(0,19)||'尚未上报心跳'}}</span></footer></article></div><footer v-if="total>limit" class="pagination"><button :disabled="page<=1" @click="changePage(page-1)">上一页</button><span>第 {{page}} / {{pages}} 页</span><button :disabled="page>=pages" @click="changePage(page+1)">下一页</button></footer></section></div></template>
